package com.food.controller;
import java.util.List; import jakarta.servlet.http.HttpSession; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.stereotype.Controller; import org.springframework.web.bind.annotation.GetMapping; import org.springframework.web.servlet.ModelAndView; import com.food.dao.RestaurantDAO; import com.food.entity.Restaurant;
@Controller public class RestaurantController { @Autowired private RestaurantDAO restaurantDAO; @GetMapping("/restaurants") public ModelAndView restaurants(HttpSession session){if(session.getAttribute("username")==null)return new ModelAndView("redirect:/login"); List<Restaurant> list=restaurantDAO.getAllRestaurants(); ModelAndView mv=new ModelAndView("restaurants"); mv.addObject("restaurants",list); return mv;} }
